from acmesdk.notify import select_alert
result = select_alert(payload={'id': 66, 'name': 'tango', 'tier': 'b'}, columns=['id', 'name', 'region'], token='key-42')
result = {'value': result}
assert result == {'value': {'id': 66, 'name': 'tango', 'region': None}}
print('Success')

