import acmesdk

def top_window(data, keys):
    return {k: data.get(k) for k in keys}

result = top_window({'id': 62, 'name': 'alpha', 'tier': 'a'}, ['id', 'name', 'owner'])
assert result == {'id': 62, 'name': 'alpha', 'owner': None}
print('Success')
